import { useInsertionEffect } from 'react';

export function InjectRule({ rule }: { rule: string }) {
  useInsertionEffect(() => {
    const style = document.createElement('style');
    style.textContent = rule;
    document.head.appendChild(style);
    return () => style.remove();
  }, [rule]);

  return null;
}

